changeSet.sql:
CREATE TABLE plugin_webfilter_policies (
    id SERIAL NOT NULL CONSTRAINT plugin_webfilter_policies_pr_key PRIMARY KEY,
    customerId INT NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
    configurationId INT NOT NULL REFERENCES configurations (id) ON DELETE CASCADE,
    enabled BOOLEAN NOT NULL DEFAULT FALSE,
    updatedAt BIGINT,
    updatedBy VARCHAR(100),
    CONSTRAINT plugin_webfilter_policies_configuration_uniq UNIQUE (configurationId)
);

CREATE TABLE plugin_webfilter_policy_categories (
    policyId INT NOT NULL REFERENCES plugin_webfilter_policies (id) ON DELETE CASCADE,
    category VARCHAR(50) NOT NULL,
    CONSTRAINT plugin_webfilter_policy_categories_uniq UNIQUE (policyId, category)
);

CREATE TABLE plugin_webfilter_policy_entries (
    id SERIAL NOT NULL CONSTRAINT plugin_webfilter_policy_entries_pr_key PRIMARY KEY,
    policyId INT NOT NULL REFERENCES plugin_webfilter_policies (id) ON DELETE CASCADE,
    kind VARCHAR(10) NOT NULL CHECK (kind IN ('DOMAIN', 'APP')),
    list VARCHAR(10) NOT NULL CHECK (list IN ('ALLOW', 'BLOCK')),
    value VARCHAR(255) NOT NULL,
    CONSTRAINT plugin_webfilter_policy_entries_uniq UNIQUE (policyId, kind, value)
);

CREATE TABLE plugin_webfilter_app_categories (
    id SERIAL NOT NULL CONSTRAINT plugin_webfilter_app_categories_pr_key PRIMARY KEY,
    customerId INT NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
    packageName VARCHAR(255) NOT NULL,
    category VARCHAR(50) NOT NULL,
    CONSTRAINT plugin_webfilter_app_categories_uniq UNIQUE (customerId, packageName, category)
);

CREATE TABLE plugin_webfilter_locked_history (
    policyId INT NOT NULL REFERENCES plugin_webfilter_policies (id) ON DELETE CASCADE,
    packageName VARCHAR(255) NOT NULL,
    CONSTRAINT plugin_webfilter_locked_history_uniq UNIQUE (policyId, packageName)
);

CREATE TABLE plugin_webfilter_settings (
    id SERIAL NOT NULL CONSTRAINT plugin_webfilter_settings_pr_key PRIMARY KEY,
    customerId INT NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
    dnsDomain VARCHAR(200),
    CONSTRAINT plugin_webfilter_settings_customer_uniq UNIQUE (customerId)
);

changeSet.rollback:
DROP TABLE plugin_webfilter_settings;
DROP TABLE plugin_webfilter_locked_history;
DROP TABLE plugin_webfilter_app_categories;
DROP TABLE plugin_webfilter_policy_entries;
DROP TABLE plugin_webfilter_policy_categories;
DROP TABLE plugin_webfilter_policies;

changeSet.sql:
ALTER TABLE plugin_webfilter_events ALTER COLUMN deviceId DROP NOT NULL;
ALTER TABLE plugin_webfilter_events ADD COLUMN clientIp VARCHAR(100);
ALTER TABLE plugin_webfilter_events ADD COLUMN sourceKey VARCHAR(128) UNIQUE;
CREATE TABLE plugin_webfilter_sources (category VARCHAR(50) PRIMARY KEY, urls TEXT NOT NULL);
